  "message": "#12 [stage-0 5/5] RUN --mount=type=secret,id=render-env,target=/run/secrets/render-env --mount=type=secret,id=bex-file-0,target=/etc/secrets/qa-note.txt,required=true [\"/bin/bash\",\"-c\",\". /opt/bex/load-env\\n/bin/cat \u003e qa_probe.rs \u003c\u003c'QA239_RUST'\\nuse std::{env,fs,io::{Read,Write},net::TcpListener};\\nfn quote(s:\u0026str)-\u003eString { let mut o=String::from(\"\\\"\"); for c in s.chars(){match c{'\"'=\u003eo.push_str(\"\\\\\\\"\"),'\\\\'=\u003eo.push_str(\"\\\\\\\\\"),'\\n'=\u003eo.push_str(\"\\\\n\"),'\\r'=\u003eo.push_str(\"\\\\r\"),'\\t'=\u003eo.push_str(\"\\\\t\"),c if c\u003c' '=\u003eo.push_str(\u0026format!(\"\\\\u{:04x}\",c as u32)),c=\u003eo.push(c)}} o.push('\"');o }\\nfn snap()-\u003eString {let b=fs::read(\"/etc/secrets/qa-note.txt\").unwrap();let h:String=b.iter().map(|v|format!(\"{:02x}\",v)).collect();format!(\"{{\\\"marker\\\":{},\\\"path\\\":{},\\\"fileHex\\\":{}}}\",quote(\u0026env::var(\"QA_MARKER\").unwrap()),quote(\u0026env::var(\"PATH\").unwrap()),quote(\u0026h))}\\nfn main(){if env::args().nth(1).as_deref()==Some(\"--snapshot\"){println!(\"{}\",snap());return}let built=fs::read_to_string(\"qa-built.json\").unwrap();let port=env::var(\"PORT\").unwrap_or(\"3000\".into());let listener=TcpListener::bind(format!(\"0.0.0.0:{}\",port)).unwrap();for incoming in listener.incoming(){let mut client=incoming.unwrap();let mut req=[0u8;4096];if client.read(\u0026mut req).is_err(){continue}let payload=format!(\"{{\\\"built\\\":{},\\\"runtime\\\":{}}}\",built.trim(),snap());let response=format!(\"HTTP/1.1 200 OK\\r\\nContent-Type: application/json\\r\\nContent-Length: {}\\r\\nConnection: close\\r\\n\\r\\n{}\",payload.len(),payload);let _=client.write_all(response.as_bytes());}}\\nQA239_RUST\\n/usr/local/cargo/bin/rustc -C linker=/usr/bin/gcc -C link-arg=-B/usr/bin qa_probe.rs -o qa-http\\n/opt/render/project/src/qa-http --snapshot \u003e qa-built.json\"]",
